include("dscommon.inc");

ds_html_header("Get Row Count");

$tablename = $_REQUEST["tablename"];
$storenum = isset($_REQUEST["storenum"]) ? $_REQUEST["storenum"] : 1;

if (empty($tablename))
  {
  echo "<H2>Error: No table name specified</H2>\n";
  ds_html_footer();
  exit;
  }

if (!($link_id=mysqli_connect())) die(mysqli_error());

// Execute COUNT(*) query
$query = "SELECT COUNT(*) FROM DS3.$tablename;";
$result = mysqli_query($link_id,$query);

if (!$result)
  {
  echo "<H2>Error executing query: " . mysqli_error($link_id) . "</H2>\n";
  mysqli_close($link_id);
  ds_html_footer();
  exit;
  }

$row = mysqli_fetch_row($result);
$rowcount = $row[0];
mysqli_free_result($result);
mysqli_close($link_id);

// Return rowcount in hidden input field (matches expected parse format from web driver)
echo "<INPUT TYPE=HIDDEN NAME=rowcount VALUE=$rowcount>\n";

ds_html_footer();
?>
